from z3 import *
labels = [Int(f'l_{g}_{i}') for g in range(5) for i in range(4)]
s = Solver()
for l in labels:
    s.add(l >= 0, l <= 46)
s.add(Distinct(labels))
diffs = []
for g in range(5):
    for a in range(4):
        for b in range(a+1,4):
            d = Abs(labels[g*4 + a] - labels[g*4 + b])
            diffs.append(d)
for g in range(4):
    for i in range(4):
        d = Abs(labels[g*4 + i] - labels[(g+1)*4 + i])
        diffs.append(d)
s.add(Distinct(diffs))
for d in diffs:
    s.add(d >=1, d<=46)
s.add(Sum([If(And(d >=1, d<=46),1,0) for d in diffs]) == 46)
s.set('timeout', 30000)
print(s.check())
